import Foundation

/// Writing Stello items into a folder (folder engine plan 4b, phase 2 part 2).
/// Swift twin of `src/lib/folder-write.js` + the parts of `src/lib/folder-v2.js` it uses;
/// both are checked against the same expected files (`FolderWriteFixtures`, generated by
/// `scripts/make-folder-write-fixtures.mjs`). Pure apart from nothing: no file I/O here.
///
/// Header values are JSON written the way JavaScript's `JSON.stringify` writes them, with
/// object keys in their original order, so a file written on the Mac and one written on
/// the web for the same item are the same bytes.
nonisolated enum FolderWriter {
    static let trashDir = ".trash"
    static let trashDays = 30.0

    // MARK: - Ordered JSON

    /// A JSON value that keeps object key order (JSONSerialization doesn't).
    indirect enum JSON: Equatable {
        case null
        case bool(Bool)
        case number(Double)
        case string(String)
        case array([JSON])
        case object(Obj)

        var string: String? { if case .string(let s) = self { return s }; return nil }
        var number: Double? { if case .number(let n) = self { return n }; return nil }
        var array: [JSON]? { if case .array(let a) = self { return a }; return nil }
        var object: Obj? { if case .object(let o) = self { return o }; return nil }
        subscript(key: String) -> JSON? { object?[key] }

        /// JS `empty()`: null, "", [] and {} are left out of a header.
        var isEmpty: Bool {
            switch self {
            case .null: return true
            case .string(let s): return s.isEmpty
            case .array(let a): return a.isEmpty
            case .object(let o): return o.isEmpty
            default: return false
            }
        }

        /// From `JSONSerialization` output or plain Swift values (dictionary keys sorted,
        /// since their order is lost anyway).
        init(any value: Any?) {
            switch value {
            case nil, is NSNull: self = .null
            case let b as Bool where type(of: b) == Bool.self: self = .bool(b)
            #if canImport(Darwin)
            case let n as NSNumber where CFGetTypeID(n) == CFBooleanGetTypeID(): self = .bool(n.boolValue)
            #endif
            case let n as NSNumber: self = .number(n.doubleValue)
            case let i as Int: self = .number(Double(i))
            case let d as Double: self = .number(d)
            case let s as String: self = .string(s)
            case let a as [Any]: self = .array(a.map { JSON(any: $0) })
            case let d as [String: Any]: self = .object(Obj(d.keys.sorted().map { ($0, JSON(any: d[$0])) }))
            default: self = .null
            }
        }
    }

    /// Ordered object: keys keep the order they were first set in (like a JS object).
    struct Obj: Equatable {
        private(set) var keys: [String] = []
        private var values: [String: JSON] = [:]
        init() {}
        init(_ pairs: [(String, JSON)]) { for (k, v) in pairs { self[k] = v } }
        var isEmpty: Bool { keys.isEmpty }
        var pairs: [(String, JSON)] { keys.map { ($0, values[$0]!) } }
        subscript(key: String) -> JSON? {
            get { values[key] }
            set {
                if let newValue {
                    if values[key] == nil { keys.append(key) }
                    values[key] = newValue
                } else if values[key] != nil {
                    values[key] = nil
                    keys.removeAll { $0 == key }
                }
            }
        }
    }

    /// `JSON.stringify(value)`.
    static func stringify(_ value: JSON) -> String {
        switch value {
        case .null: return "null"
        case .bool(let b): return b ? "true" : "false"
        case .number(let n): return jsNumber(n)
        case .string(let s): return quote(s)
        case .array(let a): return "[" + a.map(stringify).joined(separator: ",") + "]"
        case .object(let o): return "{" + o.pairs.map { quote($0.0) + ":" + stringify($0.1) }.joined(separator: ",") + "}"
        }
    }

    static func jsNumber(_ n: Double) -> String {
        guard n.isFinite else { return "null" }
        if n == n.rounded(), abs(n) < 1e21 { return String(Int64(n)) }
        var s = "\(n)"
        // Swift writes 1e-07; JavaScript writes 1e-7.
        if let e = s.firstIndex(where: { $0 == "e" || $0 == "E" }) {
            var mant = String(s[..<e]); var exp = String(s[s.index(after: e)...])
            if mant.hasSuffix(".0") { mant.removeLast(2) }
            let sign = exp.hasPrefix("-") ? "-" : "+"
            exp = String(exp.drop(while: { $0 == "-" || $0 == "+" }).drop(while: { $0 == "0" }))
            s = "\(mant)e\(sign)\(exp.isEmpty ? "0" : exp)"
        }
        return s
    }

    static func quote(_ s: String) -> String {
        var out = "\""
        for u in s.unicodeScalars {
            switch u {
            case "\"": out += "\\\""
            case "\\": out += "\\\\"
            case "\u{08}": out += "\\b"
            case "\u{0C}": out += "\\f"
            case "\n": out += "\\n"
            case "\r": out += "\\r"
            case "\t": out += "\\t"
            default:
                if u.value < 0x20 { out += String(format: "\\u%04x", u.value) } else { out.unicodeScalars.append(u) }
            }
        }
        return out + "\""
    }

    /// Order-keeping JSON parser.
    static func parse(_ text: String) -> JSON? {
        var p = Parser(Array(text.utf8))
        guard let v = p.value() else { return nil }
        p.skip()
        return p.i == p.b.count ? v : nil
    }

    private struct Parser {
        let b: [UInt8]
        var i = 0
        init(_ b: [UInt8]) { self.b = b }
        mutating func skip() { while i < b.count, [0x20, 0x09, 0x0A, 0x0D].contains(b[i]) { i += 1 } }
        mutating func value() -> JSON? {
            skip()
            guard i < b.count else { return nil }
            switch b[i] {
            case UInt8(ascii: "{"):
                i += 1; var o = Obj(); skip()
                if i < b.count, b[i] == UInt8(ascii: "}") { i += 1; return .object(o) }
                while true {
                    skip()
                    guard case .string(let k)? = str() else { return nil }
                    skip(); guard i < b.count, b[i] == UInt8(ascii: ":") else { return nil }; i += 1
                    guard let v = value() else { return nil }
                    o[k] = v
                    skip(); guard i < b.count else { return nil }
                    if b[i] == UInt8(ascii: ",") { i += 1; continue }
                    if b[i] == UInt8(ascii: "}") { i += 1; return .object(o) }
                    return nil
                }
            case UInt8(ascii: "["):
                i += 1; var a: [JSON] = []; skip()
                if i < b.count, b[i] == UInt8(ascii: "]") { i += 1; return .array(a) }
                while true {
                    guard let v = value() else { return nil }
                    a.append(v)
                    skip(); guard i < b.count else { return nil }
                    if b[i] == UInt8(ascii: ",") { i += 1; continue }
                    if b[i] == UInt8(ascii: "]") { i += 1; return .array(a) }
                    return nil
                }
            case UInt8(ascii: "\""): return str()
            case UInt8(ascii: "t"): return word("true", .bool(true))
            case UInt8(ascii: "f"): return word("false", .bool(false))
            case UInt8(ascii: "n"): return word("null", .null)
            default:
                let start = i
                while i < b.count, let c = Optional(b[i]), (c >= 0x30 && c <= 0x39) || [0x2D, 0x2B, 0x2E, 0x65, 0x45].contains(c) { i += 1 }
                guard i > start, let d = Double(String(decoding: b[start..<i], as: UTF8.self)) else { return nil }
                return .number(d)
            }
        }
        mutating func word(_ w: String, _ v: JSON) -> JSON? {
            let u = Array(w.utf8)
            guard i + u.count <= b.count, Array(b[i..<i + u.count]) == u else { return nil }
            i += u.count; return v
        }
        mutating func str() -> JSON? {
            guard i < b.count, b[i] == UInt8(ascii: "\"") else { return nil }
            i += 1
            var bytes: [UInt8] = []
            var units: [UInt16] = []
            func flushUnits() { if !units.isEmpty { bytes += Array(String(decoding: units, as: UTF16.self).utf8); units = [] } }
            while i < b.count {
                let c = b[i]
                if c == UInt8(ascii: "\"") { i += 1; flushUnits(); return .string(String(decoding: bytes, as: UTF8.self)) }
                if c == UInt8(ascii: "\\") {
                    i += 1; guard i < b.count else { return nil }
                    let e = b[i]; i += 1
                    if e == UInt8(ascii: "u") {
                        guard i + 4 <= b.count, let v = UInt16(String(decoding: b[i..<i + 4], as: UTF8.self), radix: 16) else { return nil }
                        i += 4; units.append(v); continue
                    }
                    flushUnits()
                    switch e {
                    case UInt8(ascii: "n"): bytes.append(0x0A)
                    case UInt8(ascii: "t"): bytes.append(0x09)
                    case UInt8(ascii: "r"): bytes.append(0x0D)
                    case UInt8(ascii: "b"): bytes.append(0x08)
                    case UInt8(ascii: "f"): bytes.append(0x0C)
                    default: bytes.append(e)
                    }
                    continue
                }
                flushUnits()
                bytes.append(c); i += 1
            }
            return nil
        }
    }

    // MARK: - Names and paths (folder-v2.js)

    static let itemFields = ["id", "title", "url", "kind", "site", "summary", "status",
        "added", "analyzed", "opened", "open_count", "cover", "cover_aspect",
        "review", "enrichment", "people", "places", "sources",
        "tags", "meta", "snippets", "images"]
    static let entityFields = ["id", "name", "kind", "aliases", "url", "summary", "status", "added", "analyzed", "opened",
        "open_count", "cover", "cover_aspect", "review", "enrichment", "places",
        "tags", "meta", "snippets", "images"]
    private static let listKeys: Set<String> = ["images", "snippets", "people", "sources"]
    static let peopleKinds: Set<String> = ["individual", "studio", "foundry"]

    private static func regex(_ p: String) -> NSRegularExpression { try! NSRegularExpression(pattern: p) }
    private static func replace(_ s: String, _ re: NSRegularExpression, _ with: String) -> String {
        re.stringByReplacingMatches(in: s, range: NSRange(s.startIndex..., in: s), withTemplate: with)
    }
    private static let jsSpace = CharacterSet.whitespacesAndNewlines.union(CharacterSet(charactersIn: "\u{FEFF}"))
    static func trim(_ s: String) -> String { s.trimmingCharacters(in: jsSpace) }

    /// Match key for a name: lowercase, no accents, no punctuation, single spaces.
    static func nameKey(_ name: String) -> String {
        var scalars = String.UnicodeScalarView()
        for u in name.decomposedStringWithCompatibilityMapping.unicodeScalars where !(0x300...0x36F).contains(u.value) { scalars.append(u) }
        var s = String(scalars).lowercased()
        s.removeAll { "@'’\"".contains($0) }
        return trim(replace(s, nonAlnum, " "))
    }
    private static let nonAlnum = regex("[^a-z0-9]+")
    private static let orgWords = regex("\\b(type foundry|typefoundry|foundry|type|studio|design co|design|co|inc|ltd|llc)\\b")
    private static let spaces = regex("\\s+")

    static func coreKey(_ name: String) -> String {
        let k = trim(replace(replace(nameKey(name), orgWords, " "), spaces, " "))
        return k.count >= 3 ? k : nameKey(name)
    }

    /// "south-korea" → "South Korea", "usa" → "USA".
    static func titleFromTag(_ tag: String) -> String {
        let t = trim(tag)
        if ["usa", "uk", "uae"].contains(t) { return t.uppercased() }
        return t.components(separatedBy: CharacterSet(charactersIn: "-_").union(.whitespacesAndNewlines))
            .filter { !$0.isEmpty }
            .map { $0.prefix(1).uppercased() + $0.dropFirst() }
            .joined(separator: " ")
    }

    /// folder-format.js `safeName`.
    static func safeName(_ slug: String?, fallback: String = "item") -> String {
        var out = ""
        var dash = false
        for u in (slug ?? "").decomposedStringWithCompatibilityMapping.unicodeScalars {
            let ok = (u.value >= 0x30 && u.value <= 0x39) || (u.value >= 0x41 && u.value <= 0x5A) || (u.value >= 0x61 && u.value <= 0x7A) || u == "." || u == "_" || u == "-"
            if ok { out.unicodeScalars.append(u); dash = false } else if !dash { out += "-"; dash = true }
        }
        while let f = out.first, f == "-" || f == "." { out.removeFirst() }
        while let l = out.last, l == "-" || l == "." { out.removeLast() }
        let s = String(out.prefix(120))
        return s.isEmpty ? fallback : s
    }

    static func fileName(_ name: String, _ fallback: String) -> String { safeName(nameKey(name).replacingOccurrences(of: " ", with: "-"), fallback: fallback) }
    static func entityID(_ type: String, _ name: String) -> String { "\(type)-\(safeName(nameKey(name).replacingOccurrences(of: " ", with: "-"), fallback: "x"))" }

    /// items/<YYYY>/<MM>/<name>.md from the item's added date.
    static func itemPath(added: String?, name: String) -> String {
        let a = Array((added ?? "").utf8)
        func digits(_ r: Range<Int>) -> Bool { r.upperBound <= a.count && a[r].allSatisfy { $0 >= 0x30 && $0 <= 0x39 } }
        if digits(0..<4), a.count > 4, a[4] == UInt8(ascii: "-"), digits(5..<7) {
            return "items/\(String(decoding: a[0..<4], as: UTF8.self))/\(String(decoding: a[5..<7], as: UTF8.self))/\(name).md"
        }
        return "items/undated/\(name).md"
    }

    /// folder-format.js `imageExt` (no content type).
    static func imageExt(_ path: String) -> String {
        let re = regex("\\.([A-Za-z0-9]{2,5})(?:$|\\?)")
        guard let m = re.firstMatch(in: path, range: NSRange(path.startIndex..., in: path)),
              let r = Range(m.range(at: 1), in: path) else { return "img" }
        return path[r].lowercased().replacingOccurrences(of: "jpeg", with: "jpg")
    }

    private static func squash(_ s: String) -> String { trim(replace(s, spaces, " ")) }
    private static func snippetText(_ s: JSON) -> String { trim(s.string ?? s["text"]?.string ?? "") }

    /// folder-v2.js `cleanBody`: drops sections that only repeat the summary or snippets.
    static func cleanBody(_ body: String?, summary: String?, snippets: [JSON]) -> String {
        let src = (body ?? "") as NSString
        if trim(src as String).isEmpty { return "" }
        let known = Set(snippets.map { squash(snippetText($0)) }.filter { !$0.isEmpty })
        // JS `src.split(/(?=^## )/m)`: cut before every line that starts with "## ".
        var cuts = sectionStart.matches(in: src as String, range: NSRange(location: 0, length: src.length)).map(\.range.location).filter { $0 > 0 }
        cuts.append(src.length)
        var parts: [String] = []
        var last = 0
        for c in cuts { parts.append(src.substring(with: NSRange(location: last, length: c - last))); last = c }
        let kept = parts.filter { part in
            let ns = part as NSString
            guard let m = sectionHead.firstMatch(in: part, range: NSRange(location: 0, length: ns.length)) else { return true }
            let title = trim(ns.substring(with: m.range(at: 1))).lowercased()
            let text = trim(ns.substring(with: m.range(at: 2)))
            if title == "summary" { return !(text.isEmpty || squash(text) == squash(summary ?? "")) }
            if title == "key snippets" || title == "key passages" {
                let quotes = text.components(separatedBy: "\n").filter { !$0.isEmpty }.map { trim(replace($0, quoteMark, "")) }.filter { !$0.isEmpty }
                return !quotes.allSatisfy { known.contains(squash($0)) }
            }
            return true
        }
        return trim(kept.joined())
    }
    private static let sectionStart = try! NSRegularExpression(pattern: "^## ", options: [.anchorsMatchLines])
    private static let sectionHead = try! NSRegularExpression(pattern: "^## ([^\\n]*)\\n?([\\s\\S]*)$")
    private static let quoteMark = try! NSRegularExpression(pattern: "^>\\s?")

    /// Header → file text. `fields` gives the order; empty values are left out.
    static func headerText(_ h: Obj, body: String, fields: [String] = itemFields) -> String {
        var lines = ["---"]
        let order = fields + h.keys.filter { !fields.contains($0) }
        for key in order {
            guard let v = h[key], !v.isEmpty else { continue }
            if key == "review", v == .bool(false) { continue }
            if key == "tags", case .object(let o) = v {
                lines.append("tags:")
                for (k, val) in o.pairs { lines.append("  \(k): \(stringify(val))") }
            } else if listKeys.contains(key), case .array(let a) = v {
                lines.append("\(key):")
                for entry in a { lines.append("  - \(stringify(entry))") }
            } else {
                lines.append("\(key): \(stringify(v))")
            }
        }
        lines += ["---", ""]
        var b = body
        while let l = b.unicodeScalars.last, CharacterSet.whitespacesAndNewlines.contains(l) { b.unicodeScalars.removeLast() }
        return lines.joined(separator: "\n") + (b.isEmpty ? "" : b + "\n")
    }

    struct Copy: Equatable {
        var header: Obj
        var body: String
        var modified: Double = 0
    }

    /// File text → header + body, or nil when it isn't a Stello file (folder-format.js `parseItemFile`).
    static func readCopy(_ text: String) -> Copy? {
        let src = text as NSString
        guard let open = openLine.firstMatch(in: text, range: NSRange(location: 0, length: src.length)) else { return nil }
        let from = open.range.length - 1
        let close = closeLine.firstMatch(in: text, range: NSRange(location: from, length: src.length - from))
        let headEnd = close?.range.location ?? src.length
        let head = src.substring(with: NSRange(location: open.range.length, length: max(0, headEnd - open.range.length)))
        var body = ""
        if let close {
            body = src.substring(from: close.range.location + close.range.length)
            if body.hasPrefix("\r\n") { body.removeFirst() } else if body.hasPrefix("\n") { body.removeFirst() }
        }
        var header = Obj()
        var block: String?
        for raw in head.components(separatedBy: "\n") {
            let line = raw.hasSuffix("\r") ? String(raw.dropLast()) : raw
            if trim(line).isEmpty || trim(line).hasPrefix("#") { continue }
            if line.hasPrefix("  - ") {
                guard let block, let v = parse(String(line.dropFirst(4))) else { return nil }
                var list = header[block]?.array ?? []
                list.append(v)
                header[block] = .array(list)
                continue
            }
            if line.hasPrefix("  ") {
                guard let block, let at = line.range(of: ": ") else { return nil }
                guard let v = parse(String(line[at.upperBound...])) else { return nil }
                var o = header[block]?.object ?? Obj()
                o[trim(String(line[line.index(line.startIndex, offsetBy: 2)..<at.lowerBound]))] = v
                header[block] = .object(o)
                continue
            }
            guard let at = line.firstIndex(of: ":") else { return nil }
            let key = trim(String(line[..<at]))
            let rest = trim(String(line[line.index(after: at)...]))
            if rest.isEmpty { block = key; header[key] = .null; continue }
            block = nil
            guard let v = parse(rest) else { return nil }
            header[key] = v
        }
        guard header["id"]?.string?.isEmpty == false else { return nil }
        return Copy(header: header, body: body)
    }
    private static let openLine = try! NSRegularExpression(pattern: "^---\\r?\\n")
    private static let closeLine = try! NSRegularExpression(pattern: "\\r?\\n---\\r?\\n")

    /// A copy → file text (people-kind files keep the entity layout).
    static func copyText(_ c: Copy) -> String {
        let isEntity = peopleKinds.contains(c.header["kind"]?.string ?? "") || c.header["name"].map { !$0.isEmpty && $0 != .null } == true
        return headerText(c.header, body: c.body, fields: isEntity ? entityFields : itemFields)
    }

    // MARK: - Item → file (folder-write.js itemFile)

    struct Entity: Equatable {
        var id: String
        var name: String
        var kind: String?
        var aliases: [String]
        var isPlace: Bool
        var path: String = ""
    }

    struct EntityIndex {
        var people: [String: Entity] = [:]
        var core: [String: Entity] = [:]
        var places: [String: Entity] = [:]
        init(_ entities: [Entity]) {
            for e in entities {
                if e.isPlace || e.id.hasPrefix("place-") {
                    for n in [e.name] + e.aliases { let k = FolderWriter.nameKey(n); if !k.isEmpty, places[k] == nil { places[k] = e } }
                } else {
                    for n in [e.name] + e.aliases { let k = FolderWriter.nameKey(n); if !k.isEmpty, people[k] == nil { people[k] = e } }
                }
            }
            for e in entities where !(e.isPlace || e.id.hasPrefix("place-")) && e.kind != "individual" {
                let k = FolderWriter.coreKey(e.name); if !k.isEmpty, core[k] == nil { core[k] = e }
            }
        }
    }

    struct MediaCopy: Equatable { var index: Int; var remote: String; var file: String }

    struct Output {
        var path: String
        var header: Obj
        var body: String
        var text: String
        var entities: [(path: String, text: String, entity: Entity)]
        var media: [MediaCopy]
    }

    private static let renames = ["source_url": "url", "domain": "site", "added_at": "added", "analyzed_at": "analyzed",
        "last_opened_at": "opened", "needs_review": "review", "enrichment_status": "enrichment", "metadata": "meta"]
    private static let scalars = ["id", "title", "source_url", "kind", "domain", "summary", "status",
        "added_at", "analyzed_at", "last_opened_at", "open_count", "cover_aspect", "needs_review",
        "enrichment_status", "metadata"]

    /// A JSON string field holding JSON (D1 rows) or the value itself.
    private static func parsed(_ v: JSON?) -> JSON? {
        if case .string(let s)? = v, let p = parse(s) { return p }
        return v
    }

    private static func named(_ x: JSON) -> String? {
        if let s = x.string { let t = trim(s); return t.isEmpty ? nil : t }
        if let n = x["name"]?.string { let t = trim(n); return t.isEmpty ? nil : t }
        return nil
    }

    /// folder-v2.js `splitRefs`: people and places out of author, tags and meta.
    static func splitRefs(author: JSON?, tags: inout Obj, meta: inout Obj?) -> (people: [(raw: JSON, role: String, kind: String)], places: [(name: String, kind: String)]) {
        var people: [(raw: JSON, role: String, kind: String)] = []
        var places: [(name: String, kind: String)] = []
        tags["collection"] = nil
        for k in tags["location"]?.object?.keys ?? [] { places.append((k, "country")) }
        tags["location"] = nil
        if let author, named(author) != nil { people.append((author, "author", "individual")) }
        if var m = meta {
            for key in ["location", "geography"] {
                guard let v = m[key], !isFalsy(v) else { continue }
                let list = v.array ?? [v]
                if list.allSatisfy({ named($0) != nil }) {
                    for x in list { places.append((x.string ?? x["name"]?.string ?? "", "place")) }
                    m[key] = nil
                }
            }
            for (key, role, kind) in [("author", "author", "individual"), ("maker", "maker", "individual"), ("brand", "brand", "brand"),
                                      ("typeDesigner", "designer", "individual"), ("typeFoundry", "foundry", "foundry"), ("distributedOn", "distributor", "foundry")] {
                guard let v = m[key], !isFalsy(v) else { continue }
                let list = v.array ?? [v]
                if !list.isEmpty, list.allSatisfy({ named($0) != nil }) {
                    for x in list { people.append((x, role, x["kind"]?.string.flatMap { $0.isEmpty ? nil : $0 } ?? kind)) }
                    m[key] = nil
                }
            }
            meta = m
        }
        return (people, places)
    }

    /// The value when JavaScript would call it truthy, else nil (for `a || b` chains).
    private static func truthy(_ v: JSON?) -> JSON? { v.flatMap { isFalsy($0) ? nil : $0 } }

    private static func isFalsy(_ v: JSON) -> Bool {
        switch v { case .null: return true; case .bool(let b): return !b; case .string(let s): return s.isEmpty; case .number(let n): return n == 0 || n.isNaN; default: return false }
    }

    /// JS `name.split(/\s+\/\s+|\s*\(([^)]*)\)\s*/).filter(Boolean)`.
    private static func nameParts(_ name: String) -> [String] {
        let re = regex("\\s+/\\s+|\\s*\\(([^)]*)\\)\\s*")
        let ns = name as NSString
        var out: [String] = []
        var last = 0
        for m in re.matches(in: name, range: NSRange(location: 0, length: ns.length)) {
            out.append(ns.substring(with: NSRange(location: last, length: m.range.location - last)))
            if m.range(at: 1).location != NSNotFound { out.append(ns.substring(with: m.range(at: 1))) }
            last = m.range.location + m.range.length
        }
        out.append(ns.substring(from: last))
        return out.filter { !$0.isEmpty }
    }

    /// An item (sync API shape, as ordered JSON) → its v2 file. Same rules as folder-write.js
    /// `itemFile`: an existing file keeps its path, `sources` and copied-in images; people and
    /// places are matched to the folder's own files or created.
    /// `localExts`: images with bytes on this device but no web path yet (index → file
    /// extension); they are copied in from the bytes. The web never has these.
    static func itemFile(_ item: Obj, entities: [Entity], paths: inout Set<String>, existing: (path: String, copy: Copy)?,
                         localExts: [Int: String] = [:]) -> Output {
        var ix = EntityIndex(entities)
        let kind = item["kind"]?.string ?? ""
        let isPerson = peopleKinds.contains(kind)
        func unique(_ p: String) -> String {
            var out = p; var n = 2
            while paths.contains(out.lowercased()) { out = String(p.dropLast(3)) + "-\(n).md"; n += 1 }
            paths.insert(out.lowercased())
            return out
        }
        let idString: String = item["id"]?.string ?? "item"
        let base = safeName(item["slug"]?.string, fallback: idString)
        let path: String
        if let existing { path = existing.path }
        else if isPerson { path = unique("people/\(fileName(item["title"]?.string.flatMap { $0.isEmpty ? nil : $0 } ?? base, base)).md") }
        else { path = unique(itemPath(added: item["added_at"]?.string, name: base)) }
        let up = String(repeating: "../", count: path.split(separator: "/", omittingEmptySubsequences: false).count - 1)
        let mediaName = String((path.split(separator: "/").last ?? "").dropLast(3))

        var h = Obj()
        for f in scalars { h[renames[f] ?? f] = item[f] ?? .null }
        var meta: Obj? = parsed(item["metadata"])?.object
        var tags = Obj()
        for t in parsed(item["tags"])?.array ?? [] {
            guard let tag = t["tag"]?.string else { continue }
            let cat = t["category"]?.string.flatMap { $0.isEmpty ? nil : $0 } ?? "subject"
            var group = tags[cat]?.object ?? Obj()
            group[tag] = .number(t["weight"]?.number ?? 1)
            tags[cat] = .object(group)
        }
        let snippets = parsed(item["snippets"])?.array ?? []

        let refs = splitRefs(author: item["author"], tags: &tags, meta: &meta)
        h["meta"] = meta.map { .object($0) } ?? .null
        h["snippets"] = .array(snippets)
        var created: [Entity] = []
        func person(_ raw: JSON, _ kind: String) -> Entity? {
            let name = trim(raw.string ?? raw["name"]?.string ?? "")
            if name.isEmpty { return nil }
            let parts = nameParts(name)
            for p in [name] + parts { if let hit = ix.people[nameKey(p)] { return hit } }
            for p in [name] + parts { if let hit = ix.core[coreKey(p)], hit.kind != "individual" { return hit } }
            let first = parts.first ?? name
            let k = raw["kind"]?.string.flatMap { $0.isEmpty ? nil : $0 } ?? kind
            var e = Entity(id: entityID("person", first), name: first, kind: k,
                           aliases: parts.dropFirst().filter { nameKey($0) != nameKey(first) }, isPlace: false)
            e.path = unique("people/\(fileName(e.name, e.id)).md")
            for n in [e.name] + e.aliases { ix.people[nameKey(n)] = e }
            if e.kind != "individual" { ix.core[coreKey(e.name)] = e }
            created.append(e)
            return e
        }
        func place(_ raw: String, _ kind: String) -> Entity? {
            let name = titleFromTag(raw)
            let k = nameKey(name)
            if k.isEmpty { return nil }
            if let hit = ix.places[k] { return hit }
            var e = Entity(id: entityID("place", name), name: name, kind: kind, aliases: [], isPlace: true)
            e.path = unique("places/\(fileName(name, e.id)).md")
            ix.places[k] = e
            created.append(e)
            return e
        }
        var people: [JSON] = []
        var seenPeople = Set<String>()
        for p in refs.people {
            guard let e = person(p.raw, p.kind), e.id != idString else { continue }
            if seenPeople.insert("\(e.id)|\(p.role)").inserted {
                people.append(.object(Obj([("id", .string(e.id)), ("role", .string(p.role))])))
            }
        }
        var places: [JSON] = []
        for p in refs.places { if let e = place(p.name, p.kind), !places.contains(.string(e.id)) { places.append(.string(e.id)) } }

        let prior = existing?.copy.header["images"]?.array ?? []
        var media: [MediaCopy] = []
        let images: [JSON] = (parsed(item["images"])?.array ?? []).enumerated().map { i, img in
            guard case .object(let o) = img else { return img }
            let key = truthy(o["path"]) ?? truthy(o["url"])
            if let had = prior.first(where: { (truthy($0["path"]) ?? truthy($0["url"])) == key && truthy($0["file"]) != nil }), let file = had["file"] {
                return .object(Obj([("file", file)] + o.pairs))
            }
            guard let remote = o["path"]?.string, !remote.isEmpty else {
                guard let ext = localExts[i] else { return img }
                let file = "media/\(mediaName)/\(i + 1).\(ext)"
                media.append(MediaCopy(index: i, remote: "", file: file))
                return .object(Obj([("file", .string(up + file))] + o.pairs))
            }
            let file = "media/\(mediaName)/\(i + 1).\(imageExt(remote))"
            media.append(MediaCopy(index: i, remote: remote, file: file))
            return .object(Obj([("file", .string(up + file))] + o.pairs))
        }
        let primary = images.firstIndex { $0["is_primary"] == .bool(true) }
        let coverAt = primary ?? (images.isEmpty ? nil : 0)
        let cover = coverAt.flatMap { images[$0]["file"] } ?? .null

        var header = h
        header["cover"] = cover
        header["images"] = .array(images)
        header["tags"] = .object(tags)
        header["people"] = .array(people)
        header["places"] = .array(places)
        if let s = existing?.copy.header["sources"], s.array != nil { header["sources"] = s }
        let body = cleanBody(item["body_markdown"]?.string, summary: item["summary"]?.string, snippets: snippets)
        var fields = itemFields
        if isPerson {
            let title = item["title"]?.string.flatMap { $0.isEmpty ? nil : $0 } ?? base
            header["name"] = .string(title)
            if let a = existing?.copy.header["aliases"], !a.isEmpty { header["aliases"] = a }
            header["title"] = nil; header["people"] = nil; header["sources"] = nil
            fields = entityFields
        }
        let text = headerText(header, body: body, fields: fields)
        let files = created.map { e -> (path: String, text: String, entity: Entity) in
            let eh = Obj([("id", .string(e.id)), ("name", .string(e.name)), ("kind", e.kind.map { .string($0) } ?? .null),
                          ("aliases", .array(e.aliases.map { .string($0) }))])
            return (e.path, headerText(eh, body: "", fields: entityFields), e)
        }
        return Output(path: path, header: header, body: body, text: text, entities: files, media: media)
    }

    // MARK: - Merging two copies (folder-write.js mergeCopies)

    private static func listKey(_ k: String, _ x: JSON) -> String? {
        switch k {
        case "people": return x["id"]?.string.map { "\($0)|\(x["role"]?.string ?? "")" }
        case "places": return x.string
        case "sources": return (truthy(x["id"]) ?? truthy(x["url"])).map { $0.string ?? stringify($0) }
        case "snippets": return squash(x.string ?? x["text"]?.string ?? "")
        case "images": return (truthy(x["path"]) ?? truthy(x["url"]) ?? truthy(x["file"])).map { $0.string ?? stringify($0) }
        case "aliases": return x.string.map(nameKey)
        default: return nil
        }
    }
    private static let mergedLists: Set<String> = ["people", "places", "sources", "snippets", "images", "aliases"]

    /// Two copies of one item → one, like sync conflict copies: tags and links combine, the
    /// newer copy's value wins for other fields, both notes are kept. `a` is the main copy.
    static func merge(_ a: Copy, _ b: Copy) -> Copy {
        let (newer, older) = b.modified > a.modified ? (b, a) : (a, b)
        var header = Obj()
        var keys = a.header.keys
        for k in b.header.keys where !keys.contains(k) { keys.append(k) }
        for k in keys {
            let x = newer.header[k], y = older.header[k]
            if k == "tags" {
                var out = Obj()
                for src in [y, x] {
                    for (cat, tags) in src?.object?.pairs ?? [] {
                        var group = out[cat]?.object ?? Obj()
                        for (t, w) in tags.object?.pairs ?? [] {
                            let prev = group[t]?.number ?? -Double.infinity
                            group[t] = .number(max(prev, w.number ?? 0))
                        }
                        out[cat] = .object(group)
                    }
                }
                header["tags"] = .object(out)
            } else if mergedLists.contains(k) {
                var out: [JSON] = []; var seen = Set<String>()
                for v in (x?.array ?? []) + (y?.array ?? []) {
                    guard let key = listKey(k, v), !key.isEmpty, seen.insert(key).inserted else { continue }
                    out.append(v)
                }
                header[k] = .array(out)
            } else {
                header[k] = (x == nil || x!.isEmpty) ? (y ?? .null) : x!
            }
        }
        header["id"] = a.header["id"]
        return Copy(header: header, body: mergeNotes(trim(a.body), trim(b.body)), modified: max(a.modified, b.modified))
    }

    /// Both notes kept: one inside the other keeps the longer, else the main note then the other.
    static func mergeNotes(_ main: String, _ other: String) -> String {
        if other.isEmpty || main.contains(other) { return main }
        if main.isEmpty || other.contains(main) { return other }
        return "\(main)\n\n\(other)"
    }

    // MARK: - Trash and ids

    private static let dayFormat: DateFormatter = {
        let f = DateFormatter()
        f.calendar = Calendar(identifier: .gregorian)
        f.locale = Locale(identifier: "en_US_POSIX")
        f.timeZone = TimeZone(identifier: "UTC")
        f.dateFormat = "yyyy-MM-dd"
        return f
    }()

    /// .trash/<YYYY-MM-DD>/<path>.
    static func trashPath(_ path: String, now: Date = .now) -> String { "\(trashDir)/\(dayFormat.string(from: now))/\(path)" }

    /// True when a .trash/<YYYY-MM-DD> day folder is more than 30 days old.
    static func trashExpired(_ day: String, now: Date = .now) -> Bool {
        guard day.count == 10, let d = dayFormat.date(from: day) else { return false }
        return now.timeIntervalSince(d) > trashDays * 86400
    }

    /// Item ids are UUIDs; people and places that exist only as files have person-/place- ids.
    static func isLibraryID(_ id: String) -> Bool { UUID(uuidString: id) != nil }
}
